using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change: HasData() now uses UTC for seeding timestamps.
        // Use a fixed value instead of DateTime.UtcNow to avoid migration churn.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF9 breaking change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=test",
            "MyDatabase");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change: Cosmos provider now uses "$type" as the
        // discriminator property by default instead of "Discriminator".
        // To maintain compatibility with existing documents, explicitly
        // configure the old property name.
        modelBuilder.Entity<Document>().HasDiscriminator<string>("Discriminator");
    }
}

class Document
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public string Content { get; set; } = default!;
}

