using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF9 breaking change: Migrate() can no longer be called inside a
    // manual transaction — it now manages its own transaction internally.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }

    // EF9 breaking change: Cosmos DB provider no longer supports synchronous
    // I/O. All queries must use async methods (ToListAsync, FirstAsync, etc.).
    async Task QueryCosmosAsync(CosmosDbContext cosmosDb)
    {
        // WRONG (throws InvalidOperationException in EF9):
        //   var docs = cosmosDb.Documents.ToList();
        //
        // CORRECT — use async:
        var docs = await cosmosDb.Documents.ToListAsync();
    }
}

